import os
import subprocess
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration
ALLOWED_EXTENSIONS = ['.pdf', '.docx', '.xlsx', '.png', '.jpg']
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB
UPLOAD_DIR = '/tmp/uploads'
CONVERSION_TOOL = '/usr/bin/libreoffice'

def sanitize_filename(filename):
    """Remove path traversal attempts but preserve extension"""
    basename = os.path.basename(filename)
    # Strip null bytes and control characters
    basename = re.sub(r'[\x00-\x1f]', '', basename)
    return basename

def validate_extension(filename):
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)

    if not validate_extension(filename):
        return jsonify({'error': 'Invalid file type'}), 400

    # Save uploaded file
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    filepath = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(filepath)

    # Get optional output format from query parameter
    output_format = request.args.get('format', 'pdf')

    # Build conversion command
    cmd = f'{CONVERSION_TOOL} --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {filepath}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            text=True
        )

        if result.returncode != 0:
            return jsonify({'error': 'Conversion failed', 'details': result.stderr}), 500

        output_name = os.path.splitext(filename)[0] + '.' + output_format.split('"')[0]
        output_path = os.path.join(UPLOAD_DIR, output_name)

        if os.path.exists(output_path):
            return jsonify({
                'status': 'success',
                'output': output_name,
                'download_url': f'/api/v2/download/{output_name}'
            })
        else:
            return jsonify({'error': 'Output file not generated'}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timeout'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(filepath):
            os.unlink(filepath)

@app.route('/api/v2/download/<filename>')
def download_file(filename):
    """Download converted file"""
    safe_name = sanitize_filename(filename)
    filepath = os.path.join(UPLOAD_DIR, safe_name)
    if os.path.exists(filepath):
        from flask import send_file
        return send_file(filepath)
    return jsonify({'error': 'File not found'}), 404

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
